    /**
     * Method to retrieve the Admission via AdmissionFetchOneSummary
     * @param 	summary AdmissionFetchOneSummary 
     * @return 	AdmissionFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Admission getAdmission( AdmissionFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "AdmissionFetchOneSummary arg cannot be null" );
    	
    	Admission entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Admission
        	// --------------------------------------
        	CompletableFuture<Admission> futureEntity = queryGateway.query(new FindAdmissionQuery( new LoadAdmissionFilter( summary.getAdmissionId() ) ), ResponseTypes.instanceOf(Admission.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Admission with id " + summary.getAdmissionId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


