    /**
     * assign Encounter on Admission
     * @param		command AssignEncounterToAdmissionCommand	
     * @exception	ProcessingException
     */     
	public void assignEncounter( AssignEncounterToAdmissionCommand command ) throws ProcessingException {

		// --------------------------------------------
		// load the parent
		// --------------------------------------------
		load( command.getAdmissionId() );
		
		EncounterService childDelegate 	= EncounterService.getEncounterInstance();
		AdmissionService parentDelegate = AdmissionService.getAdmissionInstance();			
		UUID childId = command.getAssignment().getEncounterId();
		Encounter child = null;
		
		try {
			// --------------------------------------
	    	// best to validate the command now
	    	// --------------------------------------    
	    	validator.validate( command );    

	    	// --------------------------------------
        	// issue the command
        	// --------------------------------------    	
    		commandGateway.sendAndWait( command );

		}
        catch( Throwable exc ) {
			final String msg = "Failed to get Encounter using id " + childId;
			LOGGER.log( Level.WARNING,  msg );
			throw new ProcessingException( msg, exc );
        }
	}

